import * as React from 'react';
import { StackPanel } from './StackPanel';
import { TextBlock } from './TextBlock';
import { Control, IControlProps, IControLState } from './Control';
import { Binding } from '@antimatterjs/react';
import { DefaultEffects, getTheme } from '@fluentui/react';

export interface IGroupBoxProps extends IControlProps
{
    Header?: string | Binding,
}
export interface IGroupBoxState extends IControLState
{
    Header?: string,
}

export class GroupBox extends Control<IGroupBoxProps, IGroupBoxState>
{
    static defaultProps: IGroupBoxProps = {
        Background: "white",
        BorderBrush: "#C0C0C0",
        BorderThickness: "1px",
        Padding: "10px"
    }

    render()
    {
        const theme = getTheme();

        return (
            <StackPanel
                Padding={(this.state.Header ? "0px 10px 10px 10px" : "10px")}>
                {this.state.Header ? (() =>
                    <TextBlock FontWeight="bold" Text={this.state.Header}/>)()
                    : null}

                <StackPanel
                    BoxShadow={DefaultEffects.elevation8}
                    Background={this.state.Background}
                    BorderBrush="#C0C0C0"
                    BorderThickness={this.state.BorderThickness}
                    Padding={this.props.Padding}>
                    {this.props.children}
                </StackPanel>

            </StackPanel>
        );
    }
}
